program.compute:
options = read('/input/options')
ids = []
for k in range(3, 5):
    for group in combinations(options, k):
        candidate = [item['id'] for item in group]
        if valid(candidate):
            ids = candidate
            break
    if len(ids) > 0:
        break
result = ids

program.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
else:
    write('/output/selection', result)
    selection = result
if status('report') == 'not_sent':
    send('report', 'team', selection)
if exists('/tmp/cache'):
    delete('/tmp/cache')

